# Let's verify by tracing through each depth level
def bfs_by_levels(graph, start):
    visited = {start: 0}
    queue = deque([start])
    levels = defaultdict(list)
    levels[0].append(start)

    while queue:
        node = queue.popleft()
        current_depth = visited[node]

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited[neighbor] = current_depth + 1
                levels[current_depth + 1].append(neighbor)
                queue.append(neighbor)

    return levels

